"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.31668",title:"Reading, Writing, Sharing, and Interacting with the World through Video",up:220,href:"https://arxiv.org/abs/2610.31668",abstract:"Video foundation models have advanced rapidly in understanding and generating visual sequences, while video world models seek to capture the underlying dynamics of the world they depict. Despite their different objectives, both concern the relationship between video observations and an evolving world. This survey adopts world modeling as a unifying lens for examining these developments. Viewing an observed video as a partial, lossy, and temporally ordered projection of a latent temporal world, we organize the literature around four complementary operations: reading infers world properties from",pdfUrl:"https://arxiv.org/pdf/2610.31668",primaryCategory:"cs.CV",published:"2026-10-22T00:00:00Z"},{id:"2610.30932",title:"UserArena: Benchmarking Interactive User Simulation for Long-Horizon Shopping Agents",up:47,href:"https://arxiv.org/abs/2610.30932",abstract:"Agentic recommendation pursues shopper goals through sequences of context-dependent decisions. Developing and evaluating such policies requires faithful recommendation world models that capture both the interactive shopping environment and users' behavioral responses over long interactions. Existing resources rarely provide long-horizon, fine-grained real-user trajectories or support trajectory-level evaluation and offline validation against production A/B results. We introduce UserArena, a real-world e-commerce interactive benchmark containing 64,729 session trajectories from 11,010 users, sp",pdfUrl:"https://arxiv.org/pdf/2610.30932",primaryCategory:"cs.IR",published:"2026-10-22T00:00:00Z"},{id:"2610.31162",title:"HiSTEVE 1.0: Harnessing Human-Interface VLA Agents for Open-World Games",up:38,href:"https://arxiv.org/abs/2610.31162",abstract:"Building virtual embodied agents that operate in open-ended games like human players is a long-standing goal requiring both long-horizon autonomy and reliable native-interface control. As a procedurally generated open world, Minecraft provides a natural testbed for studying the integration of these capabilities. Existing agents typically provide either native visuomotor control without long-horizon autonomy or high-level planning executed through environment APIs or predefined skills. To bridge this gap, we propose HiSTEVE, a hierarchical VLA agent with a capability-aware agent harness. At the",pdfUrl:"https://arxiv.org/pdf/2610.31162",primaryCategory:"cs.CV",published:"2026-10-22T00:00:00Z"},{id:"2610.32253",title:"RSIHub: A Composable Framework for Agent-Evolution Methods",up:34,href:"https://arxiv.org/abs/2610.32253",abstract:"Agent-evolution methods use execution feedback to improve prompts, skills, tools, and orchestration, but their implementations often rebuild the same experimental machinery. We present RSIHub, an open-source framework for building, comparing, and extending these methods on shared infrastructure. Recipes compose reusable operators and declare mutable resources; RSIHub supplies execution, evaluation, recovery, and lineage. Researchers can focus on evolution policy while evaluation stays outside the mutable surface and results remain tied to candidates and evaluation conditions. We instantiate AH",pdfUrl:"https://arxiv.org/pdf/2610.32253",primaryCategory:"cs.AI",published:"2026-10-23T00:00:00Z"},{id:"2610.32965",title:"RynnUnify: Towards Unified Embodied Brain",up:31,href:"https://arxiv.org/abs/2610.32965",abstract:"We introduce RynnUnify, a 16B unified embodied model that combines strong embodied understanding with long-horizon visual planning through interleaved video--language reasoning. With capabilities spanning spatial reasoning, physical prediction, and grounding, RynnUnify connects an understanding of the physical world with visual anticipation of how it evolves across successive subtasks. Building on these capabilities, we further develop an agentic extension through reinforcement learning to selectively use video predictions for reasoning about unobserved states and interaction outcomes. We also",pdfUrl:"https://arxiv.org/pdf/2610.32965",primaryCategory:"cs.RO",published:"2026-10-23T00:00:00Z"},{id:"2610.30418",title:"Agent Mosaic: Recognizing Confidentiality Leaks in Agentic LLM Systems",up:25,href:"https://arxiv.org/abs/2610.30418",abstract:"Modern LLM agents can retrieve information from accessible documents, and then disclose a sensitive conclusion assembled from them. This mosaic effect creates a critical risk for agents operating over confidential data. We quantify its realization with 30 synthetic cybersecurity, medical, and military examples, yielding 10,800 final answers from three LLM agents in controlled simulation and 1,440 answers from live agents in two open-source harnesses. Even under benign queries designed to be answerable from one document, GPT-5.6-Sol, the best performing model tested, discloses forbidden composi",pdfUrl:"https://arxiv.org/pdf/2610.30418",primaryCategory:"cs.CR",published:"2026-10-21T00:00:00Z"},{id:"2610.31198",title:"Different Tasks, Different Timesteps: Temporal Task-Aware Quantization for Diffusion Language Models",up:24,href:"https://arxiv.org/abs/2610.31198",abstract:"Diffusion Language Models (DLMs) introduce unique quantization challenges due to their iterative denoising process. In this work, we reveal that quantization sensitivity is both taskand time-dependent, with different downstream tasks exhibiting distinct precision requirements across denoising steps. We further show that these patterns can be predicted without groundtruth labels or task-specific evaluation metrics. Building on these findings, we introduce T 2Quant, a task and time-aware mixedprecision quantization framework that uses a label-free sensitivity signal to optimally allocate activat",pdfUrl:"https://arxiv.org/pdf/2610.31198",primaryCategory:"cs.AI",published:"2026-10-22T00:00:00Z"},{id:"2610.04184",title:"EvalResearchBench: Can AI Agents Build Their Own Feedback for Recursive Self-Improvement?",up:22,href:"https://arxiv.org/abs/2610.04184",abstract:"Recursive self-improvement (RSI) relies on evaluation feedback to assess progress and guide further research, yet repeatedly running complex benchmarks is costly and slows iteration. Human experts reduce this cost by selecting benchmark subsets or designing compact suites. We ask whether AI agents can automate this design process and introduce EvalResearchBench (ERB), a benchmark for autonomous evaluation research. Given target materials, development references, candidate APIs, and fixed time and API budgets, an agent called the researcher selects or synthesizes tasks, implements graders, and ",pdfUrl:"https://arxiv.org/pdf/2610.04184",primaryCategory:"cs.AI",published:"2026-10-16T00:00:00Z"},{id:"2610.27103",title:"Omni-Woodpecker: Hallucination Correction via Evidence-Prior Rebalancing for Omni LLMs",up:22,href:"https://arxiv.org/abs/2610.27103",abstract:"Recent Omni LLMs (OLLMs) have demonstrated remarkable capabilities in joint audio-visual reasoning, yet cross-modal hallucinations remain a major challenge. Existing mitigation methods mainly operate at the output level, overlooking the entanglement of grounding evidence and learned priors within fused representations. To address this issue, we propose Omni-Woodpecker (OWP), a training-free framework that shifts hallucination mitigation from output-level manipulation to conflict-conditioned representation rebalancing. Specifically, OWP first identifies cross-modal conflicts from complementary ",pdfUrl:"https://arxiv.org/pdf/2610.27103",primaryCategory:"cs.AI",published:"2026-10-19T00:00:00Z"},{id:"2610.31931",title:"Every Weight Is a Path of Shared Discrete Decisions",up:18,href:"https://arxiv.org/abs/2610.31931",abstract:"We introduce TWIG (Tree-structured Weights with Inherited Gates), a representation in which every weight of a neural network is the end of a path of small discrete decisions: a sign, a shift by a power of two, a zero gate, an index into a shared table. Weights that belong together share the upper part of their paths, and each decision is inherited by every weight below it, so it is stored once and applied once. This simple change has three consequences. Any trained network can be written as a TWIG, and when the decisions are powers of two its weight layers become circuits made almost entirely ",pdfUrl:"https://arxiv.org/pdf/2610.31931",primaryCategory:"cs.LG",published:"2026-10-22T00:00:00Z"},{id:"2610.25835",title:"Diffusion Language Models Change Speed Across Tasks and Languages",up:16,href:"https://arxiv.org/abs/2610.25835",abstract:"Diffusion language models can write several tokens in one forward pass, and they decide during generation how many passes to spend. Two outputs of the same token length can therefore vary a lot in cost. To understand the underlying factors of this cost variation, we analyze two diffusion models across 10 tasks. We find that the number of forward passes per token depends heavily on the task. Text copied or lightly edited from the input is cheap, while open-ended writing is costly. In DiffusionGemma, generating a token for story writing requires more than three times as many forward passes as fo",pdfUrl:"https://arxiv.org/pdf/2610.25835",primaryCategory:"cs.CL",published:"2026-10-19T05:47:58Z"},{id:"2610.31066",title:"Dual Exam: Controlled Evaluation of Multimodal Agents and World Models",up:16,href:"https://arxiv.org/abs/2610.31066",abstract:"World Models (WMs) can support Multimodal Agents (MAs) through simulated experience, while Agent trajectories can inform World Model refinement. Evaluating this interaction requires separate evidence about action selection and state evolution. We introduce Dual Exam, which tests Agents under fixed environment response mechanisms and World Models under fixed action interventions across physical, digital, social, and scientific domains. The Agent track compares 10 configurations on 1,088 items in 15 reporting categories. The World Model track contains 400 cases across eight scenarios; 15 configu",pdfUrl:"https://arxiv.org/pdf/2610.31066",primaryCategory:"cs.AI",published:"2026-10-22T00:00:00Z"},{id:"2610.31734",title:"DirCast: Live Esports Directing and Commentary with a Single Streaming Video-Language Model",up:15,href:"https://arxiv.org/abs/2610.31734",abstract:"A live esports broadcast needs a director who chooses which camera goes on air and a caster who talks over that choice, every second and without knowing what comes next. Streaming video language models have learned to commentate, but only over a broadcast that a human director has already produced. We study live broadcast production, in which a model receives the raw camera of every player and must both direct and commentate from the past alone. We present DirCast, a single streaming video language model that does both. Every second it scans all cameras at low resolution, decides with a hold-o",pdfUrl:"https://arxiv.org/pdf/2610.31734",primaryCategory:"cs.CV",published:"2026-10-22T00:00:00Z"},{id:"2610.29477",title:"TenetBench: A Clause-Anchored Russian Corpus for Evaluating Language Models against Professional Codes of Ethics",up:12,href:"https://arxiv.org/abs/2610.29477",abstract:"Codes of professional ethics guide and restrict specialists, who increasingly work with assistants built on large language models. Such an assistant can breach the user's code, or help the user breach it, without the user noticing. Evaluations reporting broad categories of harm cannot show how often this happens or which provision is breached. TenetBench pairs 3,433 requests conflicting with clauses of fifteen Russian-language professional codes with benign twins that differ only in the legitimacy of what is asked. An automated pipeline generates the tasks from the text of a code, so the corpu",pdfUrl:"https://arxiv.org/pdf/2610.29477",primaryCategory:"cs.CL",published:"2026-10-21T00:00:00Z"},{id:"2610.32002",title:"DraMaze: A Multi-Agent Pipeline with Future-Aware Memory for Diverse Microdrama Script Generation",up:11,href:"https://arxiv.org/abs/2610.32002",abstract:"The rapid growth of microdramas has increased demand for high-quality script production. Long-form microdrama script generation with LLMs requires both diverse plot progression and long-range narrative coherence. Our observations reveal that candidate continuations increasingly concentrate on fewer narrative mechanisms as generation progresses, while conventional retrieval may reinforce trope reuse and overlook historical information essential to future plots. To address these challenges, we propose DraMaze, a multi-agent pipeline that explores diverse causal paths through trope memory-guided ",pdfUrl:"https://arxiv.org/pdf/2610.32002",primaryCategory:"cs.CL",published:"2026-10-22T00:00:00Z"},{id:"2610.32770",title:"On-Policy Self-Training: Data-Free Self-Improvement in Large Language Models",up:11,href:"https://arxiv.org/abs/2610.32770",abstract:"On-policy self-distillation enables post-training foundation models without relying on stronger external teachers. However, existing approaches rely on ground-truth question-answer pairs, human-curated problem sets, or other supervised signals. In this work, we reformulate on-policy self-distillation as a self-training framework, driven by self-generated question-answer pairs and privileged reasoning demonstrations. We push supervision to the limit: guided solely by coarse, high-level topic descriptions, the model synthesizes its own curriculum of queries and privileged reasoning traces withou",pdfUrl:"https://arxiv.org/pdf/2610.32770",primaryCategory:"cs.CL",published:"2026-10-23T00:00:00Z"},{id:"2610.17821",title:"FLOMSS: Generative Music Source Separation by Flow Matching",up:10,href:"https://arxiv.org/abs/2610.17821",abstract:"Music source separation (MSS) has been conventionally addressed by discriminative methods. Recently, flow matching has emerged as a strong generative paradigm for modeling complex data distributions, with successful applications across diverse domains. These advances motivate us to systematically investigate flow matching for MSS in a four-source (Vocals, Bass, Drums, Other) setting in full-band stereo. Specifically, we investigate prediction targets, flow paths, single-source versus multi-source modeling, and mixture consistency constraints. Beyond the signal-level metrics commonly used for M",pdfUrl:"https://arxiv.org/pdf/2610.17821",primaryCategory:"cs.SD",published:"2026-10-14T00:00:00Z"},{id:"2610.22722",title:"The LLM-Attacker: A Unified Red-Team Framework for Privacy Evaluation of Split and Distributed LLM Systems",up:10,href:"https://arxiv.org/abs/2610.22722",abstract:"Split language models keep input text on a client but send intermediate representations to a server. Attacks can reconstruct text from these messages. Comparing privacy evaluations is difficult when attackers see different messages, know different model weights or use different datasets and recovery measures. We present LLM-Attack Suite, a framework that records these choices and lets researchers check, compare and extend an evaluation. Compatible attacks reuse recorded messages, and their predictions are saved for independent scoring. The scoring rule requires a linked undefended reference be",pdfUrl:"https://arxiv.org/pdf/2610.22722",primaryCategory:"cs.CR",crossrefDoi:"https://doi.org/10.1145/3711896.3736570",year:2025,openalexId:"https://openalex.org/W4412877164",published:"2026-10-15T00:00:00Z",crossrefIssued:"2025-08-03"},{id:"2610.28950",title:"HyperDrone: Simulation-to-Reality Transfer at Millions of Frames per Second",up:10,href:"https://arxiv.org/abs/2610.28950",abstract:"We present HyperDrone, an extremely fast quadrotor simulator focused on high-performance batch rendering that is more than 20x faster than existing state-of-the-art batch quadrotor simulators. HyperDrone combines highly optimized multirotor dynamics with HyperLux, a new ray-tracing engine that supports Nvidia OptiX, Vulkan, Apple Metal and WebGPU backends that takes full advantage of modern ray-tracing hardware, capable of running both components entirely on the GPU. HyperLux renders RGB, depth, semantic/instance segmentation, surface normals and optical flow observations at configurable level",pdfUrl:"https://arxiv.org/pdf/2610.28950",primaryCategory:"cs.RO",published:"2026-10-20T00:00:00Z"},{id:"2610.24383",title:"IF-MAP: Influence-Function-Inspired Agent Prioritization in Multi-Agent Systems",up:9,href:"https://arxiv.org/abs/2610.24383",abstract:"Improving every agent in an LLM-based multi-agent system can be prohibitively costly, making it important to identify which agent should be prioritized to achieve the greatest system-level gain with limited resources. Failure attribution can inform this decision, but an agent's responsibility for failures does not directly reveal the system-level gains achievable by improving it. We therefore introduce IF-MAP, an influence-function-inspired method for identifying agents with high potential for system-level improvement. For each agent, IF-MAP measures end-to-end loss changes under controlled se",pdfUrl:"https://arxiv.org/pdf/2610.24383",primaryCategory:"cs.AI",published:"2026-10-17T00:00:00Z"},{id:"2610.23234",title:"MultiAgent-OPD: End-to-End Training of Hierarchical Multi-Agent Systems with On-Policy Distillation",up:8,href:"https://arxiv.org/abs/2610.23234",abstract:"In a hierarchical multi-agent system, a Leader assigns tasks and subagents carry them out. Jointly training the Leader and the subagents is difficult because a final answer gives only indirect feedback to the subagents. An LLM judge can score the performance of the subagents, but these scores depend on the judge's own assessment of the quality of subagents' responses. We present MultiAgent-OPD, which combines on-policy distillation with reinforcement learning to jointly train a shared-parameter Leader-Searcher-Answerer team end to end. We first train a Teacher in a Searcher-Answerer workflow u",pdfUrl:"https://arxiv.org/pdf/2610.23234",primaryCategory:"cs.CL",published:"2026-10-20T00:00:00Z"},{id:"2610.24385",title:"Bridging Exploration and Persona: Information-Directed Dueling for Test-Time Agent Personalization",up:8,href:"https://arxiv.org/abs/2610.24385",abstract:"Effective test-time personalization requires LLM agents to adapt to query-dependent user preferences from lightweight interaction. We study persona selection with binary comparisons between candidate responses as the online signal. We present ID-TAP, a scalable, IDS-inspired neural dueling-bandit framework for large discrete persona spaces. ID-TAP combines a query-conditioned neural utility model with a lightweight Bradley-Terry explorer, and transfers comparison evidence across related queries through similarity-weighted warm starts. The neural model shares statistical strength across queries",pdfUrl:"https://arxiv.org/pdf/2610.24385",primaryCategory:"cs.AI",published:"2026-10-17T00:00:00Z"},{id:"2610.30043",title:"TARSphere: A Robot-Oriented Full-Stack Framework for Long-Horizon Embodied Agents in Evolving Physical and Social Environments",up:8,href:"https://arxiv.org/abs/2610.30043",abstract:"Robots must act under physical and social constraints while adapting to changes in their environment and human needs. Existing embodied-agent systems often focus on specified goals or abstract execution into symbolic actions, limiting evaluation in an evolving world. We introduce TARSphere, a robot-oriented full-stack framework for physically and socially grounded long-horizon embodied agents. TARSphere-Infra runs robot policies in a physics simulator with embodied NPCs and constrained dialogue. An event-driven finite-state machine (FSM) uses completed actions and delivered information to upda",pdfUrl:"https://arxiv.org/pdf/2610.30043",primaryCategory:"cs.RO",published:"2026-10-21T00:00:00Z"},{id:"2610.30006",title:"Building Auditable AI Text Detectors with Sparse Autoencoders",up:7,href:"https://arxiv.org/abs/2610.30006",abstract:"AI-generated text detectors are increasingly deployed in consequential settings---peer review, education, admissions, journalism, and content moderation---where their outputs directly affect individuals. Yet the strongest detectors are fine-tuned neural classifiers whose decisions are opaque, while transparent alternatives (stylometric and linguistic-feature classifiers) underperform them by wide margins. We present a pipeline that converts a fine-tuned neural detector into a classifier that operates on human-readable concepts. We accomplish this by training sparse autoencoders (SAEs) directly",pdfUrl:"https://arxiv.org/pdf/2610.30006",primaryCategory:"cs.CL",published:"2026-10-21T00:00:00Z"},{id:"W4393160747",title:"ExpeL: LLM Agents Are Experiential Learners",up:0,href:"https://doi.org/10.1609/aaai.v38i17.29936",doi:"https://doi.org/10.1609/aaai.v38i17.29936",year:2024,openalexId:"https://openalex.org/W4393160747"},{id:"W4407759090",title:"A-Mem: Agentic Memory for LLM Agents",up:0,href:"https://doi.org/10.52202/085713-0593",doi:"https://doi.org/10.52202/085713-0593",year:2025,openalexId:"https://openalex.org/W4407759090"},{id:"W4391620956",title:"Understanding the planning of LLM agents: A survey",up:0,href:"https://doi.org/10.48550/arxiv.2402.02716",doi:"https://doi.org/10.48550/arxiv.2402.02716",year:2024,openalexId:"https://openalex.org/W4391620956"}]}}]);